import json
import time
import urllib.error
import urllib.request
from datetime import datetime, timezone
from decimal import Decimal, ROUND_HALF_UP

BASE = 'http://localhost:8080'
token = None
request_count = 0
refresh_count = 0
rate_limit_count = 0
retry_count = 0


def retry_delay(headers, body, attempt):
    raw = headers.get('Retry-After') if headers else None
    if raw:
        try:
            return max(0.0, float(raw))
        except ValueError:
            pass
    if isinstance(body, dict):
        for key in ('retry_after', 'retry_after_seconds', 'wait_seconds'):
            if key in body:
                try:
                    return max(0.0, float(body[key]))
                except (TypeError, ValueError):
                    pass
    return min(10.0, 0.5 * (2 ** min(attempt, 5)))


def raw_json(path, method='GET', auth=False):
    global token, request_count, refresh_count, rate_limit_count, retry_count
    attempt = 0
    while True:
        headers = {}
        if auth:
            if token is None:
                token = [REDACTED_SECRET]'/token', method='POST', auth=False)['token']
                refresh_count += 1
            headers['Authorization'] = f'Bearer {token}'
        req = urllib.request.Request(BASE + path, method=method, headers=headers)
        try:
            request_count += 1
            with urllib.request.urlopen(req, timeout=20) as resp:
                data = resp.read()
            return json.loads(data)
        except urllib.error.HTTPError as exc:
            data = exc.read()
            try:
                body = json.loads(data) if data else {}
            except json.JSONDecodeError:
                body = {}
            if exc.code == 401 and auth:
                token = None
                retry_count += 1
                attempt += 1
                continue
            if exc.code == 429:
                rate_limit_count += 1
                retry_count += 1
                delay = retry_delay(exc.headers, body, attempt)
                time.sleep(delay)
                attempt += 1
                continue
            if 500 <= exc.code < 600:
                retry_count += 1
                time.sleep(retry_delay(exc.headers, body, attempt))
                attempt += 1
                continue
            raise RuntimeError(f'{method} {path}: HTTP {exc.code}: {body}') from exc
        except (urllib.error.URLError, TimeoutError, json.JSONDecodeError) as exc:
            retry_count += 1
            time.sleep(retry_delay(None, {}, attempt))
            attempt += 1
            if attempt > 20:
                raise RuntimeError(f'{method} {path} repeatedly failed') from exc

seen = {}
duplicates = 0
page = 1
total_pages = None
while True:
    payload = raw_json(f'/orders?page={page}', auth=True)
    if payload.get('page') "'!= page:
        raise RuntimeError(f'"'wrong page returned: requested {page}, got {payload.get(\"page\")}')
    if total_pages is None:
        total_pages = payload['total_pages']
    elif payload['total_pages'] "'!= total_pages:
        raise RuntimeError('"'total_pages changed during traversal')
    for order in payload['items']:
        oid = order['id']
        if oid in seen:
            duplicates += 1
            if order "'!= seen[oid]:
                raise RuntimeError(f'"'duplicate order {oid} has conflicting data')
        else:
            seen[oid] = order
    expected_next = None if page == total_pages else f'/orders?page={page + 1}'
    if payload.get('next') "'!= expected_next:
        raise RuntimeError(f'"'unexpected next link on page {page}: {payload.get(\"next\")"'!r}'"')
    if payload.get('next') is None:
        break
    page += 1
if page "'!= total_pages:
    raise RuntimeError(f'"'stopped at page {page} of {total_pages}')

start = datetime(2025, 3, 1, tzinfo=timezone.utc)
end_exclusive = datetime(2025, 6, 1, tzinfo=timezone.utc)
qualifying = []
for order in seen.values():
    if order['status'] "'!= '"'shipped':
        continue
    stamp = order['placed_at']
    parsed = datetime.fromisoformat(stamp.replace('Z', '+00:00'))
    if parsed.tzinfo is None:
        raise RuntimeError(f'order {order[\"id\"]} has timezone-naive timestamp')
    placed_utc = parsed.astimezone(timezone.utc)
    if start <= placed_utc < end_exclusive:
        qualifying.append(order)

customers = {}
by_region = {'north': 0, 'south': 0, 'east': 0, 'west': 0}
for order in qualifying:
    cid = order['customer_id']
    if cid not in customers:
        customers[cid] = raw_json(f'/customers/{cid}', auth=True)
    customer = customers[cid]
    region = customer['region']
    if region not in by_region:
        raise RuntimeError(f'unknown region {region"'!r} for customer {cid}'"')
    amount = Decimal(order['amount_cents'])
    discount = Decimal(customer['discount_pct'])
    discounted = (amount * (Decimal(100) - discount) / Decimal(100)).quantize(Decimal('1'), rounding=ROUND_HALF_UP)
    by_region[region] += int(discounted)

result = {
    'total_cents': sum(by_region.values()),
    'order_count': len(qualifying),
    'duplicates_skipped': duplicates,
    'by_region': by_region,
}
print(json.dumps({'result': result, 'audit': {
    'pages': total_pages,
    'unique_orders': len(seen),
    'customers_cached': len(customers),
    'requests': request_count,
    'token_refreshes': refresh_count,
    'rate_limits': rate_limit_count,
    'retries': retry_count,
}}, indent=2))
PY"

